def linalg_lu_solve(LU, pivots, B, *, left=True, adjoint=False):
    """
    Solve the linear system AX = B using the LU factorization of A.

    Args:
        LU: (*, n, n) compact LU factorization matrix
        pivots: (*, n) pivot indices (1-indexed)
        B: (*, n, k) right-hand side matrix
        left: if True, solve AX = B; if False, solve XA = B
        adjoint: if True, solve A^H X = B

    Returns:
        X: (*, n, k) solution matrix
    """
    logger.debug("GEMS LINALG_LU_SOLVE")

    if LU.ndim < 2 or B.ndim < 2:
        raise ValueError("LU and B must be at least 2D")
    if LU.shape[-1] != LU.shape[-2]:
        raise ValueError("LU must be a square matrix")
    n = LU.shape[-1]
    if B.shape[-2] != n:
        raise ValueError("B must have compatible dimensions with LU")

    if LU.numel() == 0 or B.numel() == 0:
        return B.clone()

    batch = math.prod(LU.shape[:-2])
    nrhs = B.shape[-1]

    # Make contiguous working copies
    LU_work = LU.reshape(batch, n, n).contiguous()
    piv_work = pivots.reshape(batch, n).contiguous()
    X = B.reshape(batch, n, nrhs).clone()

    # Choose block size based on nrhs
    if nrhs <= 8:
        block_k = 8
    elif nrhs <= 16:
        block_k = 16
    else:
        block_k = 32

    # Tune num_warps: 1 warp for very small problems to reduce scheduling overhead
    if n <= 8:
        num_warps = 1
    elif n <= 32:
        num_warps = 1
    else:
        num_warps = 4

    grid = (batch, triton.cdiv(nrhs, block_k))

    with torch.no_grad():
        linalg_lu_solve_kernel[grid](
            LU_work,
            piv_work,
            X,
            n,
            nrhs,
            LU_work.stride(0),
            LU_work.stride(1),
            LU_work.stride(2),
            piv_work.stride(0),
            piv_work.stride(1),
            X.stride(0),
            X.stride(1),
            X.stride(2),
            BLOCK_K=block_k,
            num_warps=num_warps,
        )

    return X.reshape(B.shape)
